/* TOSCANINI_UI/webapp/app/globals.css */

:root {
  --paper: #f7f5f0;
  --ink: #1c1b19;
  --line: #d9d4c8;
  --accent: #8a4b2a;
  --muted: #6f6a5e;
  --sheet: #ffffff;
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  padding: 0;
  background: var(--paper);
  color: var(--ink);
  font: 15px/1.5 -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
}

.conv {
  position: relative;
  max-width: 760px;
  margin: 0 auto;
  padding: 24px 20px 40px;
}

.conv-row {
  padding: 10px 0;
  border-bottom: 1px solid var(--line);
}

.conv-composer {
  position: sticky;
  bottom: 12px;
  margin-top: 16px;
  background: var(--sheet);
  border: 1px solid var(--line);
  border-radius: 999px;
  padding: 8px 14px;
}

.conv-composer-note {
  margin-top: 4px;
  font-size: 12px;
  color: var(--muted);
  padding: 0 6px;
}

@media (max-width: 1180px) {
  .conv { padding-bottom: calc(24px + env(safe-area-inset-bottom, 0px)); } /* R477 (audit mobile): keep clearance for the sticky composer over the last row + home indicator */
  .sheet { bottom: calc(12px + env(safe-area-inset-bottom, 0px)); }
  .sheet-grabber { margin-bottom: 4px; }
}

@media (max-width: 880px) {
  .conv { padding: 16px 14px; }
  .conv-composer { bottom: calc(8px + env(safe-area-inset-bottom, 0px)); } /* R477 (audit mobile): lift the pill off the home indicator */
  .conv-composer-note { padding: 0 6px calc(2px + env(safe-area-inset-bottom, 0px)); } /* R477 (audit mobile): note row sits below the pill; same inset so the stack clears the home indicator */
}
